    for body in [0.,1.]: # Match material-body identity before matching coordinates across meshes.
        ai=np.flatnonzero(a['features'][:na,5]==body);bi=np.flatnonzero(b['features'][:nb,5]==body);d,j=cKDTree(b['xyz'][bi]).query(a['xyz'][ai]);dist[ai]=d;indices[ai]=bi[j] # Avoid mapping a moving slave node to an identically located fixed master node.
    assert dist.max()<1.e-9 # Compare only actual coincident nodes of the same physical body without interpolation or learned projection.
    au=a['states'][:,:na,:3];bu=b['states'][:,indices,:3];scale=max(float(np.linalg.norm(bu)),1.e-15);uerror=float(np.linalg.norm(au-bu)/scale);aa=json.loads((base_folder/'audit.json').read_text());ba=json.loads((fine_folder/'audit.json').read_text());ar=np.array([[r['normal_reaction_N'],r['shear_drive_N']] for r in aa['records']]);br=np.array([[r['normal_reaction_N'],r['shear_drive_N']] for r in ba['records']]);nominal=max(np.linalg.norm(br,axis=1).max(),1.);reaction=float(np.max(np.linalg.norm(ar-br,axis=1))/nominal) # Use a path-wide load scale so zero-force opening frames do not create meaningless relative blowups.
    ac=a['states'][:,:na,12];bc=b['states'][:,:nb,12];ap=float(np.max(ac));bp=float(np.max(bc));peakerror=abs(ap-bp)/max(abs(bp),1.e-12);asmax=float(np.max(np.abs(a['states'][:,:,3:9])));bsmax=float(np.max(np.abs(b['states'][:,:,3:9])));stresspeakerror=abs(asmax-bsmax)/max(bsmax,1.e-12) # Keep local peak sensitivity separate from global force and displacement convergence.
