    axes[0].set(xlabel='Prescribed tangential displacement [mm]',ylabel='Drive reaction [kN]',title='Native friction response');axes[1].set(xlabel='Load-path pseudo-time',ylabel='Normal support reaction [kN]',title='Changing normal load');axes[2].set(xlabel='Load-path pseudo-time',ylabel='Minimum physical slave gap [micrometres]',title='Actual opening and recontact');fig.savefig(f.OUT/'friction_fullfield_paths.png',dpi=180);fig.savefig(f.OUT/'friction_fullfield_paths.pdf');plt.close(fig) # Export scientific plots tied to complete source fields.
